/**
 * 改造自 shadcn 原装 base-lyra dialog（https://ui.shadcn.com/r/styles/base-lyra/dialog.json，MIT）。
 * 与上游的差异：
 * 1. 动效改由 `motion` 属性选预设（ADR 0021）。`Dialog` 收 `motion`，经 context 交给 `DialogContent`；
 *    弹层渲染 `data-motion`，遮罩固定用 `fade`。删掉弹层与遮罩上的 tw-animate-css 类
 *    （`duration-100`、`data-open:animate-in`、`fade-*`、`zoom-*`）；上游的手感保留为预设 `zoom`。
 * 2. import 改成消费者落点：Button 取 `@/components/ui/button`，关闭图标直接用 lucide 的 `XIcon`
 *    （上游写 IconPlaceholder，由 shadcn add 换成 lucide，结果相同）。
 * 3. 删掉 `DialogTitle` 上的 `cn-font-heading`：它是 shadcn 的标题字体标记，本系统不用标题字体（ADR 0004）。
 * 此外只有格式化、两条 Biome 豁免注释，以及把 `-translate-x-1/2 -translate-y-1/2` 合写成 `-translate-1/2`（lint 要求），
 * 其余类名逐字保留。
 */
import { Dialog as DialogPrimitive } from "@base-ui/react/dialog";
import { cn } from "cn";
import { XIcon } from "lucide-react";
import { type ComponentProps, createContext, use } from "react";
import { Button } from "@/components/ui/button";

/**
 * 对话框支持的动效预设（ADR 0021）。缺省 `pop`。
 * - `pop`：淡入加缩放 96%→100%，200ms。
 * - `fade`：只淡入淡出，150ms。
 * - `slide-up`：从下方 16px 升起并淡入，220ms。
 * - `zoom`：Lyra 原版，淡入加缩放 95%，100ms。
 */
type DialogMotion = "fade" | "pop" | "slide-up" | "zoom";

const DialogMotionContext = createContext<DialogMotion>("pop");

function Dialog({
  motion = "pop",
  ...props
}: DialogPrimitive.Root.Props & { motion?: DialogMotion }) {
  return (
    <DialogMotionContext value={motion}>
      <DialogPrimitive.Root data-slot="dialog" {...props} />
    </DialogMotionContext>
  );
}

function DialogTrigger({ ...props }: DialogPrimitive.Trigger.Props) {
  return <DialogPrimitive.Trigger data-slot="dialog-trigger" {...props} />;
}

function DialogPortal({ ...props }: DialogPrimitive.Portal.Props) {
  return <DialogPrimitive.Portal data-slot="dialog-portal" {...props} />;
}

function DialogClose({ ...props }: DialogPrimitive.Close.Props) {
  return <DialogPrimitive.Close data-slot="dialog-close" {...props} />;
}

function DialogOverlay({ className, ...props }: DialogPrimitive.Backdrop.Props) {
  return (
    <DialogPrimitive.Backdrop
      data-slot="dialog-overlay"
      data-motion="fade"
      className={cn(
        // biome-ignore lint/plugin: 与上游逐字一致的遮罩色。遮罩在亮暗两种模式下都是压暗，不随主题换色。
        "fixed inset-0 isolate z-50 bg-black/10 supports-backdrop-filter:backdrop-blur-xs",
        className,
      )}
      {...props}
    />
  );
}

function DialogContent({
  className,
  children,
  showCloseButton = true,
  ...props
}: DialogPrimitive.Popup.Props & {
  showCloseButton?: boolean;
}) {
  const motion = use(DialogMotionContext);
  return (
    <DialogPortal>
      <DialogOverlay />
      <DialogPrimitive.Popup
        data-slot="dialog-content"
        data-motion={motion}
        className={cn(
          // biome-ignore lint/nursery/noTailwindArbitraryValue: 与上游逐字一致的窄屏边距（左右各留 1rem）。
          "fixed top-1/2 left-1/2 z-50 grid w-full max-w-[calc(100%-2rem)] -translate-1/2 gap-4 rounded-none bg-popover p-4 text-xs/relaxed text-popover-foreground ring-1 ring-foreground/10 outline-none sm:max-w-sm",
          className,
        )}
        {...props}
      >
        {children}
        {showCloseButton && (
          <DialogPrimitive.Close
            data-slot="dialog-close"
            render={<Button variant="ghost" className="absolute top-2 right-2" size="icon-sm" />}
          >
            <XIcon />
            <span className="sr-only">Close</span>
          </DialogPrimitive.Close>
        )}
      </DialogPrimitive.Popup>
    </DialogPortal>
  );
}

function DialogHeader({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="dialog-header"
      className={cn("flex flex-col gap-1 text-left", className)}
      {...props}
    />
  );
}

function DialogFooter({
  className,
  showCloseButton = false,
  children,
  ...props
}: ComponentProps<"div"> & {
  showCloseButton?: boolean;
}) {
  return (
    <div
      data-slot="dialog-footer"
      className={cn("flex flex-col-reverse gap-2 sm:flex-row sm:justify-end", className)}
      {...props}
    >
      {children}
      {showCloseButton && (
        <DialogPrimitive.Close render={<Button variant="outline" />}>Close</DialogPrimitive.Close>
      )}
    </div>
  );
}

function DialogTitle({ className, ...props }: DialogPrimitive.Title.Props) {
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      className={cn("text-sm font-medium", className)}
      {...props}
    />
  );
}

function DialogDescription({ className, ...props }: DialogPrimitive.Description.Props) {
  return (
    <DialogPrimitive.Description
      data-slot="dialog-description"
      className={cn(
        "text-xs/relaxed text-muted-foreground *:[a]:underline *:[a]:underline-offset-3 *:[a]:hover:text-foreground",
        className,
      )}
      {...props}
    />
  );
}

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  type DialogMotion,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
  DialogTrigger,
};
